//Real pose handlers reached by459eb0, including57da0.58590/58500 queries
//and44cac0 reset are recorded leaves; deterministic RNG is real executable.
import ghidra.app.script.GhidraScript;import ghidra.app.emulator.EmulatorHelper;import java.io.*;
public class ZNov04PoseHandlerOracle extends GhidraScript{
 static final long U=0x5e30c8L,S=0x7fff0000L,RET=0x12345000L;
 long read(EmulatorHelper e,long a,int n){byte[]b=e.readMemory(toAddr(a),n);long v=0;for(int i=0;i<n;i++)v|=(b[i]&255L)<<(8*i);return v;}void put(EmulatorHelper e,long a,int n,long v)throws Exception{e.writeMemoryValue(toAddr(a),n,v);}void back(EmulatorHelper e)throws Exception{long sp=e.readRegister("ESP").longValue(),ret=read(e,sp,4);e.writeRegister("ESP",sp+4);if(!e.run(toAddr(ret),null,monitor))throw new Exception(e.getLastError());}
 public void run()throws Exception{try(PrintWriter out=new PrintWriter(getScriptArgs()[0])){int[]phases={27,28,29,30,31,34,38,41,43,45};long[]fns={0x458430,0x459180,0x458350,0x459170,0x457e20,0x457d00,0x457d50,0x4572b0,0x459110,0x4584a0};for(int k=0;k<phases.length;k++)for(int s=0;s<256;s++){EmulatorHelper e=new EmulatorHelper(currentProgram);try{e.writeMemory(toAddr(U),new byte[384]);e.writeMemory(toAddr(0x58aaaa),new byte[16384]);put(e,U+44,2,500);put(e,U+46,2,600);put(e,U+192+44,2,500+(s%5-2)*40);put(e,U+192+46,2,600+(s/5%5-2)*40);int cell=((600+11)*8&0xff80)+((500+5)>>4);put(e,0x58aaaa+cell,1,s%7==0?9:0);put(e,U+0x35,1,phases[k]);put(e,U+0x7c,1,0);put(e,U+4,1,60);put(e,U+0x71,1,0x31);put(e,U+0x7e,2,s*37);put(e,U+0x80,1,new int[]{0,1,2,10,11,20,127,128,255}[s%9]);put(e,U+0x32,2,new int[]{-1,0,1,2,3,4,5,6,8,9,10,32767}[s/3%12]);put(e,U+0x82,2,new int[]{-1,0,1,2,3,4,255}[s/7%7]);put(e,U+0x39,1,s%8);put(e,U+0x88,2,0x7134);put(e,0x622dc0,1,s%2==0?0:255);put(e,0x622dc4,1,0);for(int i=0;i<5;i++)put(e,0x622cdc+i*4,4,(s*(i+1)+i+1)&0xffffffffL);
 for(long p:new long[]{RET,0x458590,0x458500,0x44cac0})e.setBreakpoint(toAddr(p));e.writeRegister("ESP",S);put(e,S,4,RET);put(e,S+4,4,U);if(!e.run(toAddr(fns[k]),null,monitor))throw new Exception(e.getLastError());int queries=0,scans=0,relative=-1,resets=0;while(e.readRegister("EIP").longValue()!=RET){long pc=e.readRegister("EIP").longValue();if(pc==0x458590){queries++;e.writeRegister("EAX",s%7==0?1:0);}else if(pc==0x458500){scans++;relative=e.readRegister("EDX").intValue()&255;e.writeRegister("EAX",s%5==0?0x100+5:0xff00);}else{resets++;}back(e);}
 out.print("{\"phase\":"+phases[k]+",\"scenario\":"+s+",\"queries\":"+queries+",\"scans\":"+scans+",\"relative\":"+relative+",\"resets\":"+resets);for(int[]f:new int[][]{{0x35,1},{0x32,2},{0x39,1},{0x7e,2},{0x80,1},{0x82,2},{0x88,2},{0x71,1}}){long v=read(e,U+f[0],f[1]);if(f[0]==0x32||f[0]==0x82)v=(short)v;out.print(",\"u"+f[0]+"\":"+v);}for(int i=0;i<5;i++)out.print(",\"rng"+i+"\":"+read(e,0x622cdc+i*4,4));out.println("}");}finally{e.dispose();}}}}
}
